//! chime-local floria spawn helper for live-gateway integration tests.}//!}//! Mirrors the contract of `cotest::scenarios::_helpers::floria_bootstrap`}//! but is duplicated here on purpose: cotest itself depends on chime, so we}//! cannot import the cotest helper without creating a circular dependency.}//!}//! Behavior:}//!   1. Locate the floria binary via `FLORIA_BIN` env var (path to executable)}//!      or fall back to the sibling-checkout convention}//!      `<contrix-dev>/floria/target/debug/floria[.exe]`.}//!   2. Allocate a free local TCP port; render a minimal YAML config that}//!      binds floria to `127.0.0.1:<port>` with one `custom` pushkin (the}//!      pushkin is never actually invoked by the chime tests — they exercise}//!      `bridge/describe`, `integration/describe`, `/health`, and a}//!      `cx.push.notify` POST whose response delivery shape we assert).}//!   3. Spawn floria with `SOFLARE_CONF` pointing at the rendered config.}//!   4. Poll `<base_url>/health` until it returns 2xx or the deadline passes.}//!   5. Return a [`SpawnedFloria`] handle whose `Drop` kills + reaps the}//!      child process so test threads cannot leak orphans.}//!}//! Returns `Ok(None)` on **any** missing pre-requisite (binary not located,}//! port allocation failure, config render failure, spawn failure, health}//! probe timeout). Callers in `tests/live_floria_integration.rs` treat the}//! `None` arm as a silent skip — operators who want a hard failure should}//! point `FLORIA_BIN` at a known-good binary and retry.}//!}//! ## Operator pre-requisites}//!}//! For the live-floria integration tests to actually run (rather than}//! silent-skip), build floria once in a sibling checkout:}//!}//! ```text}//! cd ../floria}//! cargo build --bin floria}//! ```}//!}//! Or set `FLORIA_BIN=/path/to/floria` before invoking}//! `cargo test --locked --all-features`.}}#![allow(dead_code)] // each integration test only consumes a subset of the API.}}use std::{}    env,}    fs::File,}    io::Write,}    net::TcpListener as StdTcpListener,}    path::{Path, PathBuf},}    process::{Child, Command, Stdio},}    sync::{}        Arc,}        atomic::{AtomicBool, Ordering},}    },}    time::{Duration, Instant},}};}}use tokio::{}    io::{AsyncReadExt, AsyncWriteExt},}    net::TcpListener as TokioTcpListener,}    task::JoinHandle,}};}}/// Aggregated handle for a spawned floria: rendered config + child server +}/// the in-test custom-pushkin sink that swallows delivery POSTs so floria's}/// `dispatch_notification` returns OK instead of timing out against an}/// unbound placeholder URL.}///}/// `Drop` shuts the sink, removes the temp config file, and kills + reaps}/// the child process.}pub struct SpawnedFloria {}    /// Base URL of the spawned floria HTTP listener (e.g. `http://127.0.0.1:54321`).}    pub base_url: String,}    /// Path to the rendered config file. Held so the file can be deleted on drop.}    config_path: PathBuf,}    child: Option<Child>,}    sink_shutdown: Arc<AtomicBool>,}    sink_task: Option<JoinHandle<()>>,}}}}impl SpawnedFloria {}    /// Construct an absolute URL against the spawned floria base.}    pub fn url(&self, path: &str) -> String {}        if path.starts_with('/') {}            format!("{}{path}", self.base_url)}        } else {}            format!("{}/{path}", self.base_url)}        }}    }}}}}impl Drop for SpawnedFloria {}    fn drop(&mut self) {}        // Signal the sink first so floria's last in-flight delivery sees a}        // closed socket instead of hanging on the now-dead listener.}        self.sink_shutdown.store(true, Ordering::SeqCst);}        if let Some(handle) = self.sink_task.take() {}            handle.abort();}        }}        if let Some(mut child) = self.child.take() {}            let _ = child.kill();}            let _ = child.wait();}        }}        let _ = std::fs::remove_file(&self.config_path);}    }}}}}/// Top-level orchestrator: locate binary → start a delivery sink → render}/// config (pointing the custom pushkin at the sink) → spawn floria → wait}/// for `/health`. See module docs for the silent-skip contract.}pub async fn spawn_floria() -> Option<SpawnedFloria> {}    let floria_bin = locate_floria_binary()?;}    let bind_port = free_port().ok()?;}    let bind_addr = format!("127.0.0.1:{bind_port}");}    let base_url = format!("http://{bind_addr}");}}    // Allocate the sink port up-front so we can bake it into the config.}    let sink_port = free_port().ok()?;}    let sink_shutdown = Arc::new(AtomicBool::new(false));}    let sink_task = spawn_sink(sink_port, sink_shutdown.clone()).await?;}}    let config_path = render_floria_config(bind_port, sink_port).ok()?;}}    let mut command = Command::new(&floria_bin);}    command}        .env("SOFLARE_CONF", &config_path)}        .env("RUST_LOG", "warn")}        .stdout(Stdio::null())}        .stderr(Stdio::null());}}    let child = command.spawn().ok()?;}    let handle = SpawnedFloria {}        base_url,}        config_path,}        child: Some(child),}        sink_shutdown,}        sink_task: Some(sink_task),}    };}}    if !wait_for_health(&handle.base_url, Duration::from_secs(30)).await {}        // Drop kills the child + removes the config + tears down the sink.}        drop(handle);}        return None;}    }}    Some(handle)}}}}/// Resolve the floria executable path: explicit env override first, then the}/// sibling-checkout convention. Returns `None` when neither is a regular file.}fn locate_floria_binary() -> Option<PathBuf> {}    if let Ok(value) = env::var("FLORIA_BIN")}        && !value.trim().is_empty()}    {}        let candidate = PathBuf::from(value);}        if candidate.is_file() {}            return Some(candidate);}        }}    }}    let exe_name = if cfg!(windows) {}        "floria.exe"}    } else {}        "floria"}    };}    let chime_manifest = Path::new(env!("CARGO_MANIFEST_DIR"));}    let workspace_root = chime_manifest.parent()?;}    let candidate = workspace_root}        .join("floria")}        .join("target")}        .join("debug")}        .join(exe_name);}    candidate.is_file().then_some(candidate)}}}}/// Render the minimum YAML config floria needs to come up green:}/// loopback bind on the supplied port, in-memory dedup, no rate limits,}/// anonymous `notify_auth`, and one `custom` pushkin pointing at the}/// in-test delivery sink listening on `sink_port`.}///}/// The config is written under `std::env::temp_dir()` with a per-PID +}/// per-port suffix so concurrent test threads can't clobber each other.}fn render_floria_config(bind_port: u16, sink_port: u16) -> std::io::Result<PathBuf> {}    let body = format!(}        "http:\n  bind_addresses:\n    - 127.0.0.1\n  port: {bind_port}\n  notify_dedup_ttl_seconds: 0\n  notify_dedup:\n    backend: memory\n    key_prefix: chime-live-floria\n  notify_auth: {{}}\n  notify_rate_limits:\n    window_seconds: 60\n\napps:\n  chime.live.placeholder:\n    type: custom\n    url: http://127.0.0.1:{sink_port}/chime-live-floria-sink\n"}    );}}    let path = env::temp_dir().join(format!(}        "chime-live-floria-{}-{}.yaml",}        std::process::id(),}        bind_port}    ));}    let mut file = File::create(&path)?;}    file.write_all(body.as_bytes())?;}    file.flush()?;}    Ok(path)}}}}/// Spawn a tiny tokio TCP listener on `127.0.0.1:<port>` that accepts each}/// HTTP/1.1 request and replies `200 OK` with an empty JSON body. Floria's}/// custom pushkin POSTs delivery requests here and treats the 200 as}/// "delivered" so `/api/v1/push/notify` returns `accepted=N` instead of}/// `temporarily_unavailable`.}///}/// The listener exits when the supplied `shutdown` flag is set OR when the}/// task is aborted on `Drop`. It intentionally swallows protocol errors —}/// it's a test sink, not an HTTP server.}async fn spawn_sink(port: u16, shutdown: Arc<AtomicBool>) -> Option<JoinHandle<()>> {}    let listener = TokioTcpListener::bind(("127.0.0.1", port)).await.ok()?;}    let task = tokio::spawn(async move {}        loop {}            if shutdown.load(Ordering::SeqCst) {}                break;}            }}            let accept = tokio::time::timeout(Duration::from_millis(250), listener.accept()).await;}            let Ok(Ok((mut socket, _))) = accept else {}                // Either the timeout fired (loop again to re-check shutdown)}                // or accept itself failed (don't tight-loop on a broken fd).}                if accept.is_ok() {}                    tokio::time::sleep(Duration::from_millis(50)).await;}                }}                continue;}            };}            tokio::spawn(async move {}                // Read whatever the client sends until headers end. We}                // don't parse — just wait for the request to be drained}                // enough that hyper-on-the-other-side considers it sent.}                let mut buf = [0u8; 2048];}                let _ =}                    tokio::time::timeout(Duration::from_millis(500), socket.read(&mut buf)).await;}                let response = "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 2\r\nConnection: close\r\n\r\n{}";}                let _ = socket.write_all(response.as_bytes()).await;}                let _ = socket.shutdown().await;}            });}        }}    });}    Some(task)}}}}fn free_port() -> std::io::Result<u16> {}    let listener = StdTcpListener::bind("127.0.0.1:0")?;}    Ok(listener.local_addr()?.port())}}}}async fn wait_for_health(base_url: &str, timeout: Duration) -> bool {}    let client = match reqwest::Client::builder()}        .timeout(Duration::from_secs(2))}        .build()}    {}        Ok(c) => c,}        Err(_) => return false,}    };}    let url = format!("{base_url}/health");}    let cutoff = Instant::now() + timeout;}    while Instant::now() < cutoff {}        if let Ok(resp) = client.get(&url).send().await}            && resp.status().is_success()}        {}            return true;}        }}        tokio::time::sleep(Duration::from_millis(25